export function getScannedProductsByCategory(category: 'Slipper' | 'Sandal' | 'Shoe' | 'Wedge'): Product[] {
  const slugMap: Record<string, string> = {
    Slipper: 'slippers-slides',
    Sandal: 'sandals-floaters',
    Shoe: 'sports-casual-shoes',
    Wedge: 'wedges-heel-support'
  };
  const targetSlug = slugMap[category];
  return scannedProducts.filter((p) => p.category?.slug === targetSlug);
}

export function getScannedCatalogStats() {
  return {
    totalVerified: scannedProducts.length,
    byCategory: {
      Slipper: scannedProducts.filter((p) => p.category?.slug === 'slippers-slides').length,
      Sandal: scannedProducts.filter((p) => p.category?.slug === 'sandals-floaters').length,
      Shoe: scannedProducts.filter((p) => p.category?.slug === 'sports-casual-shoes').length,
      Wedge: scannedProducts.filter((p) => p.category?.slug === 'wedges-heel-support').length
    },
    byBrand: {
      Sparx: scannedProducts.filter((p) => p.brand === 'Sparx').length,
      Walkaroo: scannedProducts.filter((p) => p.brand === 'Walkaroo').length
    }
  };
}
